@startuml

class OOBank {}

class OrganizationalUnit {}

class Division extends OrganizationalUnit {}

class Subdivision extends OrganizationalUnit {}

class Branch extends Subdivision {
  + address
  + number
}

class AccountType {
  + interestRate
  + monthlyFee
  + privileges
}

class Account {
  + accountNumber
  + balance
  + creditOrOverdraftLimit
}

class MortgageAccount extends Account {
  + collateralProperty
}

class CheckingAccount extends Account {}

class CreditCardAccount extends Account {
  + expiryDate
}

class Client {}

class Employee {}

OOBank "1" -- "*" Division
OOBank "1" -- "*" Subdivision
Division "1" -- "*" Subdivision
Division "1" -- "*" Employee
Division "1" -- "1" Employee : manager
Branch "1" -- "*" Account
Branch "1" -- "*" Client
Client "1" -- "*" Account
Client "*" -- "1" Employee : personal banker

AccountType "1" -- "*" Account

@enduml

